function MazeMain:__init()
    self.lightRoomsDic = {} -- Dictionary<string, List<Renderer>>; key: roomName, 比如: "1", "2-up"
    self.tmpBubbles = {} -- Dictionary<int, MazeUI_Bubble>; key: trackNodeGO id, 也是 eventKey.id
    self.catchedEventKeys = {} -- LinkedList<EventKey> -> array

    self.chests = {} -- Dictionary<string, GameObject>; key: chest key, 比如: "2.1-chest", 直接是 gameobj 节点名字;

    self.last2TrackNodeGO = nil -- SimpleTrack.TrackNodeGO  上上一次
    self.lastTrackNodeGO = nil -- SimpleTrack.TrackNodeGO
    self.nextTrackNodeGO = nil -- SimpleTrack.TrackNodeGO
    self.tgtTrackNodeGO = nil  -- SimpleTrack.TrackNodeGO

    self.handleMazeTableFile = nil -- HandleMazeTableFile

    -- 一组 函数指针:
    self.HandleMazeGear = nil           -- IEnumerator()
    self.WhenEnterGear = nil            -- void(EventKey)
    self.WhenLeaveGear = nil            -- void()
    self.ReadSavedDataToPuzzle = nil    -- void(String)
    self.SaveDataFromPuzzle = nil       -- String()
    self.IsPuzzleBeSolved = nil         -- boolean()
    self.PuzzleCustomFunc = nil         -- void(eventKey.keyStr),  puzzle 自定义的事件
    self.IsSkipWhenReload = nil         -- boolean(string), 有些 eventData 需要在读档阶段被忽略, puzzle 实例用此函数来管理
    self.CustomJobWhenAfter = nil       -- void(string)


    self.isFstFrame = true
    self.move_t = 1.0           -- [0f,1f] 区间值; 一定是从 0f 运动向 1f;
    self.isRoleMoving = false   -- 由于 move_t 不精确, 故用此 flag 来记录状态;
    self.isInPuzzle = false     -- 当 role 进入到某些谜题中时(如 迷宫2 的棋盘), 此时禁止玩家移动到其它 tracknodego, 除非解开谜题
    
    self.isInGear = false       -- role 是否踩在 gear 上面;
    self.isLastInGear = false   -- 上一帧的 isInGear 值

    self.puzzleHanleState = Maze2DStates.PuzzleHandleState.Idle


    self.isEnter = false -- Enter() 函数是否调用
    --self.isLoadAsyncFinish = false

