    self.isShowTipsPopup = false
end


function MazeMain:__delete()
    self.mainCamera = nil
    self.mazeInput = nil
  
    self.coroutineRets = nil
    self.loaders = nil
    self.iconTextures = nil
end


function MazeMain:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象

    for i,co in pairs(self.coroutineRets) do 
        if not isNull(co) then
            cs_coroutine.stop(co)
            co = nil
        end
    end
    self.coroutineRets = nil

    ---:
    for i,loader in pairs(self.loaders) do 
        if not isNull(loader) then 
            loader:Release()
            loader = nil
        end
    end
    self.loaders = nil

    self:Delete()    
end



function MazeMain:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    ---@type MapDecryptionComponent
    self.mapDecryptionComponent = MapDecryptionMgr:GetComponent()
end




-- 统一管理所有 协程返回值:
function MazeMain:CollectCoroutineRets( ret_ )
    table.insert( self.coroutineRets, ret_ )
end



