function MazeMain:IsPrepared()
    return  ( not isNull(Maze2DStates.mapId) ) 
        and ( not isNull(Maze2DStates.groupId) ) 
        and ( not isNull(Maze2DStates.mapDecryptionHomeDatas) )
end 



function MazeMain:DelayInit()

    assert( self.cameraPivot )
    assert( self.cameraInitPos )
    assert( self.bubbleCanvas )
    assert( self.vcam )
    assert( self.trackBrainBehaviour )
    assert( self.lightRoomGroup )
    assert( self.chestGroup )
    assert( self.uiRoleBH )

    Maze2DStates.quitWaitFrames = -1

    Maze2DStates.isInAutoControl = 0
    --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl + 1 -- !!! Must 
    Maze2DStates.AddIsInAutoControl() -- !!! Must 

    GameUtils.SetUICameraProjection(true) -- ui相机 设为正交

    -- ==============================:
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    -- ==============================:
    -- 播放迷宫 bgm: 
    Maze2DSounds.PlayMusic( Maze2DSounds.musics.bgm_festival_map )

    -- ==============================:
    -- 等待 外部将必要数据写到 Maze2DStates;  主要是后端传来的 迷宫配置和存档
    coroutine.yield(Yielders.EndOfFrame)
    for i=0, 100 do
        if self:IsPrepared() == true then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
        coroutine.yield(Yielders.EndOfFrame)
    end 
    if self:IsPrepared() == false then 
        printError( "始终没能等到 Prepared ... " )
    end 

    -- ==============================:
    self.mapId = string.sub(Maze2DStates.groupId, 1,1) -- string, "1","2","3","4" 
    assert( (self.mapId=='1') or (self.mapId=='2') or (self.mapId=='3') or (self.mapId=='4'), "mapId = " .. tostring(self.mapId)  ) -- 目前只有 4 个迷宫

    self.trackBrain = self.trackBrainBehaviour.Env

    -- ==============================:
    self.handleMazeTableFile = HandleMazeTableFile.New( self.trackBrain )
    self.handleMazeTableFile:Read( Maze2DStates.groupId )

    -- ==============================:
    -- 异步加载资源
    cs_coroutine.yield_return( self:LoadAsync() )

    -- ==============================:
    -- 查找所有 lightRooms:
    local lightRooms = {} -- SpriteRenderer[] table
    local idComps = self.lightRoomGroup:GetComponentsInChildren(typeof(IDComp),true) -- 包含自己; idComps: Array
    for i=0, idComps.Length-1 do
        local idComp = idComps[i] -- ID component
        if idComp.stringId == "LightRoom" then 
            assert( (not isNull(idComp.gameObject)) and (idComp.gameObject ~= self.lightRoomGroup.gameObject), "lightRoomGroup 自己不能兼任 LightRoom" )

            local sr = KTool.GetComponent(idComp.gameObject, typeof(SpriteRenderer))
            assert( not isNull(sr) )
            table.insert( lightRooms, sr )
        end
    end

    -- 查找所有 chests:
    local chestTFs = self.chestGroup:GetComponentsInChildren(typeof(Transform),true) -- 包含自己; Array
    for i=0, chestTFs.Length-1 do
        local chestTF = chestTFs[i] -- ID component
        if chestTF.gameObject ~= self.chestGroup.gameObject then -- 不包含父节点自己
            self.chests[chestTF.name] = chestTF.gameObject
            chestTF.gameObject:SetActive( false ) -- 粗暴地熄灭...
        end
    end

    -- 检查 lightRooms 中的数据是否正确:
    assert( #lightRooms == table.count(self.handleMazeTableFile.IDsInRooms), 
        "#lightRooms = " .. #lightRooms .. ", IDsInRooms num = " .. table.count(self.handleMazeTableFile.IDsInRooms) 
    )
    self.lightRoomsDic = {}
    for i,sr in ipairs(lightRooms) do
        assert( not isNull(self.handleMazeTableFile.IDsInRooms[sr.name]) )

        -- 每一个 room 都可能有数个面片, 需要被同时隐藏或显示 
        local ary = {}
        local spriteRenderers = sr:GetComponentsInChildren(typeof(SpriteRenderer),true) -- 包含自己; idComps: Arra
        for j=0, spriteRenderers.Length-1 do
            local spriteRenderer = spriteRenderers[j]
            if not isNull(spriteRenderer) then 
                spriteRenderer.enabled = false -- 初始化阶段直接将所有 room 设暗
                table.insert( ary, spriteRenderer )
            end
        end
        self.lightRoomsDic[sr.name] = ary
    end
    
    self.mainCamera = URPCameraController.Instance.mainCamera -- camera 已在 Onenable() 阶段完成复制
    self.mazeInput = MazeInput.New( self, self.mainCamera, self.vcam, self.DoHitTrackNodeGOOrBubble )  
    
    ----
    self.eventConf = {
        [Constants.EventNames.UICommonPopupWindowClose] = Bind(self, self.OnEventCloseRewardDialogListener),
    }
    for key, func in pairs(self.eventConf) do
        Events.AddListener(key, func)
    end


    -- ==============================:
    self.uiRole = self.uiRoleBH.Env 
    assert( self.uiRole )
    self.uiRole:Prepare( self.vcam, self.cameraPivot,  self.mazeInput )

    -- 等待 trackBrain 异步加载结束:
    while true do
        if self.trackBrain.isReadingTrackDataAsync == false then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
        coroutine.yield(Yielders.EndOfFrame)
    end


    do -- !!! 补丁: 如果 mainCamera 为空, 等待;  若等待时间过长, 则释放玩家操作 界面ui 的权限;
        local waitI = 0
        while true do
            if isNotNull( URPCameraController.Instance.mainCamera ) then 
                break
            end

            waitI = waitI + 1
            -- 时间太久就释放控制权
            if waitI > 120 then 
                Maze2DStates.isInAutoControl = 0 -- !!! 强制释放 
            end 
            coroutine.yield(Yielders.EndOfFrame)  
        end
    end

    self.bubbleCanvas.worldCamera = URPCameraController.Instance.mainCamera -- !!!!!!! MUST 否则这个 canvas 的射线检测坐标系会错位

    -- ==============================:
    -- MapDecryptionTrackingDataEntity[]
    local trackingDataEntityList = self.mapDecryptionComponent:GenerateTrackingDataEntityList()
    self.unlockTrackQuestRefId = trackingDataEntityList[ checkInt(Maze2DStates.mapId) ].questId
    --print( "tpr 99 unlockTrackQuestRefId = " .. ((self.unlockTrackQuestRefId==nil) and "nil" or self.unlockTrackQuestRefId ) )
    
    -- ======================= First Frame =====================:
    -- 要确保 trackBrain 已经准备好了;
    self:PreparePuzzle()

    self.nextTrackNodeGO = self.trackBrain:FindTrackNodeGO(self.handleMazeTableFile.startEventKey.id)
    self.last2TrackNodeGO = self.lastTrackNodeGO
    self.lastTrackNodeGO = self.nextTrackNodeGO

    -- 隐藏所有 trackNodeGOs:
    self.trackBrain:HideAllTrackNodeGOs()

    -- 让 role 放在正确的位置上;
    --self.uiRole:RolePivotTF().position = self.lastTrackNodeGO.pos
    self.uiRole:SetRolePosImmediately( self.lastTrackNodeGO.pos )

    -- 相机直接对齐 role
    self.cameraPivot.position = self.mazeInput:CalcSafetyPos( self.uiRole:RolePivotTF().position )

    if isUseSavedData and table.count( Maze2DStates.mapDecryptionHomeDatas.playerMapQuestInfo ) > 0  then
        -- 读取存档:
        cs_coroutine.yield_return( self:ReadSavedData() )
    else 
        -- 从章节初始位置开始:        
        cs_coroutine.yield_return( self:RunFirstEvent() )
    end 
    
    -- ==============================:
    --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl - 1 -- !!! Must 
    Maze2DStates.MinusIsInAutoControl() -- !!! Must 
    self.isEnter = true
end




---@return System.Collections.IEnumerator
function MazeMain:LoadAsync( mapId )

    self.loaders = {} -- dic<string,loader>

    --  异步加载 iconTextures:
    local isNeedLoadIconTexture = table.count(self.handleMazeTableFile.iconPaths) > 0 -- boolean
    if isNeedLoadIconTexture then 
        for path,j in pairs(self.handleMazeTableFile.iconPaths) do
            self.loaders[path] = TextureLoader.Load(path, nil, CS.Engine.Modules.LoaderMode.Async, true)
        end
    end

    --  异步加载 uiBubbles:
    self.loaders["plot"]   = ResourceModule.LoadBundleAsync( uiBubblePaths["plot"], nil, true ) -- 不设回调, 不删除资源
    self.loaders["gear"]   = ResourceModule.LoadBundleAsync( uiBubblePaths["gear"], nil, true ) -- 不设回调, 不删除资源
    self.loaders["chest"]  = ResourceModule.LoadBundleAsync( uiBubblePaths["chest"], nil, true ) -- 不设回调, 不删除资源
    self.loaders["battle"] = ResourceModule.LoadBundleAsync( uiBubblePaths["battle"], nil, true ) -- 不设回调, 不删除资源
    self.loaders["boss"]   = ResourceModule.LoadBundleAsync( uiBubblePaths["boss"], nil, true ) -- 不设回调, 不删除资源

    -- 等待所有资源加赞完毕:
    local isAnyLoading = true 
    while isAnyLoading do 
        coroutine.yield(Yielders.EndOfFrame)
        isAnyLoading = false
        for i,loader in pairs(self.loaders) do 
            if not loader.IsCompleted then 
                isAnyLoading = true
                break
            end
        end
    end

    -- 确认各资源加载成功, 并使用它们:
    if isNeedLoadIconTexture then 
        for path,j in pairs(self.handleMazeTableFile.iconPaths) do
            assert( self.loaders[path].IsSuccess )
            self.iconTextures[path] = self.loaders[path].Asset
        end
    end
    ---:
    assert( self.loaders["plot"].IsSuccess )
    assert( self.loaders["gear"].IsSuccess )
    assert( self.loaders["chest"].IsSuccess )
    assert( self.loaders["battle"].IsSuccess )
    assert( self.loaders["boss"].IsSuccess )

    self.UIPlotPrefab   = self.loaders["plot"].ResultObject     -- GameObject
    self.UIGearPrefab   = self.loaders["gear"].ResultObject     -- GameObject
    self.UIChestPrefab  = self.loaders["chest"].ResultObject    -- GameObject
    self.UIBattlePrefab = self.loaders["battle"].ResultObject   -- GameObject
    self.UIBossPrefab   = self.loaders["boss"].ResultObject     -- GameObject
    assert( self.UIPlotPrefab and self.UIGearPrefab and self.UIBattlePrefab and self.UIBossPrefab and self.UIChestPrefab )
    ---:
    --self.isLoadAsyncFinish = true
end




