        self.HandleMazeGear = self.puzzleSelf.HandlePuzzle
        self.WhenEnterGear = self.puzzleSelf.WhenEnterGear
        self.WhenLeaveGear = self.puzzleSelf.WhenLeaveGear
        self.ReadSavedDataToPuzzle = self.puzzleSelf.ReadSavedDataToPuzzle
        self.SaveDataFromPuzzle = self.puzzleSelf.SaveDataFromPuzzle
        self.PuzzleCustomFunc = self.puzzleSelf.PuzzleCustomFunc
        self.IsSkipWhenReload = self.puzzleSelf.IsSkipWhenReload
        self.CustomJobWhenAfter = self.puzzleSelf.CustomJobWhenAfter

    elseif Maze2DStates.groupId == "402" then 
        -- 暂时啥也不需要 

    else 
        assert(false,"currentMazeChapter 参数有误: "..Maze2DStates.groupId)
    end
end



function MazeMain:Update()
    if self.isEnter == false then 
        return
    end

    -- ================== 刷新 uiRole ==================:
    self.uiRole:SelfUpdate()

    -- ================== 离开 gear 气泡后的事件 ==================:
    if self.isLastInGear == true and self.isInGear == false then -- 离开 gear 的第一帧:
        if not isNull(self.WhenLeaveGear) then
            self.WhenLeaveGear(self.puzzleSelf) -- 函数指针
        end
    end
    self.isLastInGear = self.isInGear

    -- ================== 自动运行期间, 屏蔽后续所有操作 !!! ==================:
    if Maze2DStates.IsInAutoControlLegal() == false then
        return
    end

    -- ================== 若在上一帧 捕获到一个 迷宫事件, 在此处理 ==================:
    if #self.catchedEventKeys > 0 then
        self:CollectCoroutineRets( cs_coroutine.start(self.RunCatchedEvents, self) )
    end

    -- ================== 若在上一帧 捕获到一个 机关事件, 在此处理 ==================:
    if self.puzzleHanleState == Maze2DStates.PuzzleHandleState.FirstFrame then
        --print(  "~~~ tpr ~~~ 若在上一帧 捕获到一个 机关事件, 在此处理" )
        self.puzzleHanleState = Maze2DStates.PuzzleHandleState.Handling
        self:CollectCoroutineRets( cs_coroutine.start(self.RunPuzzleCallBack, self) )
    end

    -- =================== 屏幕缩放, 屏幕滑动, trakNodeGo 或 bubble 的点击处理 ===========:
    self.mazeInput:MainUpdate()
    
end




-- =============================================================== Self -> ================================================================== -- 


---@param toushPos Vector3
---@return System.Collections.IEnumerator
function MazeMain:DoHitTrackNodeGOOrBubble( toushPos, isPointerOverGameObject_ )

    print(  "~~~ tpr ~~~ 按下鼠标/点到画面" )

    local trackNodeGO = nil -- TrackNodeGO
    local bubble      = nil -- MazeUI_Bubble

    -- ----- 处理 非ui元素 的点击 -----:

    if isNull(self.mainCamera) then -- !!! 曾经出现过 mainCamera 为 nil 的情况...
        return
    end

    local tmpToushPos = Vector3( toushPos.x, toushPos.y, 0 ) -- 转 Vector3 格式
    local ray = self.mainCamera:ScreenPointToRay(tmpToushPos) -- Ray

    local RaycastRet = Physics.Raycast(ray) -- boolean,RaycastHit
    local hit = nil
    if RaycastRet then
        hit = KTool.GetRaycastHitByTouch(ray)
        -- if( not isNull(hit) ) then
        --     print( "hit = " .. hit.collider.gameObject.name )
        -- end
    end
    --print( "RaycastRet = " .. tostring(RaycastRet) )

    -- 当玩家点击到 地图上的 TrackNodeGO
    if      RaycastRet == true 
        and (not isNull(hit)) 
        and isPointerOverGameObject_ == false -- 不是 ui 元素
    then
        local idComp = KTool.GetComponent(hit.collider.gameObject, typeof(IDComp))
        if not isNull(idComp) then 
            if idComp.stringId == "TrackNodeGO" then -- 如今不能在 go 上挂载 c# TrackNodeGO 脚本了, 只能用此方法来确认 go 的身份
                --print( "--s-- idComp.id = " .. tostring(idComp.id) )
                trackNodeGO = self.trackBrain:FindTrackNodeGO( idComp.id )
            end
        end
    end

    ----- 处理 bubble 的点击 -----:
    if isNull(trackNodeGO) then

        local results = KTool.UIRaycast( self.bubbleCanvas, Vector2(toushPos.x, toushPos.y) ) -- List<RaycastResult>
        if results.Count > 0 then -- 默认只处理 第一个元素;
            -- 气泡:
            --print( "results.Count = " .. tostring(results.Count) .. ";  results[0] = " .. results[0].gameObject.name )

            local resultParentGO = results[0].gameObject.transform.parent.gameObject
            local idComp = KTool.GetComponent(resultParentGO, typeof(IDComp)) -- IDComp
            if (not isNull(idComp)) and (MazeUI_Bubble.CheckTypeID(idComp.id) == true) then

                -- 播放 bubble 受击动画:
                local bubbleComp = KTool.GetComponent(resultParentGO, typeof(LuaBehaviour)).Env -- MazeUI_Bubble
                assert( bubbleComp, "没绑定 MazeUI_Bubble LuaBehaviour" )
                bubbleComp:PlayBtnPressAnimation()

                local bubbleId,bubbletype = MazeUI_Bubble.StringToIdAndType(idComp.stringId)
                --print( "==88== bubble.id = "..tostring(bubbleId) .. "; idComp.stringId = " .. idComp.stringId )
                trackNodeGO = self.trackBrain:FindTrackNodeGO( bubbleId )
            end
        end
    end

    -- 正式处理玩家的 点击:
    if not isNull(trackNodeGO) then
        --print(  "~~~ tpr ~~~ 正式处理玩家的 点击 trackNodeGO.id = " .. tostring(trackNodeGO.id) )
        self:CollectCoroutineRets( cs_coroutine.start(self.WhenHitTrackNodeGOOrBubble, self, trackNodeGO) )
    end
end




---@param trackNodeGO TrackNodeGO
---@return System.Collections.IEnumerator
function MazeMain:WhenHitTrackNodeGOOrBubble( trackNodeGO )

    assert( not isNull(trackNodeGO) )
    assert( not isNull(trackNodeGO.gameObj) )

    -- -1- 原地, 无需移动
    -- -2- 无法到达目的地
    if (trackNodeGO == self.lastTrackNodeGO) or (self.trackBrain:SearchTracks(self.lastTrackNodeGO, trackNodeGO) == false) then 
        print( "原地, 无需移动, 无法到达目的地" )
        return -- yield break;
    end

    -- 从现在起, 玩家的输入 就暂时被迷宫屏蔽了;
    --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl + 1; -- !!!!!! MUST
    Maze2DStates.AddIsInAutoControl() -- !!! Must 

    print( "koko -- 处理 bubble 开始:  MazeMain:WhenHitTrackNodeGOOrBubble -1-" )

    -- -------------------------------------------:
    -- 如果 screenZoom 被玩家改过了, 那么先缩放回原初 zoom 值
    -- 同时将 cameraPivot 对齐 role:
    cs_coroutine.yield_return(self.mazeInput:BackToInitScreenZoomAndLookAtRole())

    --  -------------------------------------------:
    -- 等待一下:
    cs_coroutine.yield_return( Maze2DStates.Wait_0D3_Seconds )

    -- -------------------------------------------:
    -- 让 role 按路线移动到 目的地:

    -- 配置第一段运动的 track 信息:
    self.tgtTrackNodeGO = trackNodeGO
    self.nextTrackNodeGO = self.lastTrackNodeGO.nextTrackNodeGO -- 跑第一段
    self.move_t = 0.0
    self.isRoleMoving = true

    if self.lastTrackNodeGO ~= self.nextTrackNodeGO then -- todo: 这个判断可能是不需要的

        if isNull(self.lastTrackNodeGO) or isNull(self.nextTrackNodeGO) then
            -- !!! 曾经出现过 nextTrackNodeGO 为 nil 的情况
            assert(self.lastTrackNodeGO)
            assert(self.nextTrackNodeGO)

        else
            -- ============== 正常情况: =================

            local trackPesist = self.trackBrain:FindTrackPesistInData( self.lastTrackNodeGO, self.nextTrackNodeGO ) -- TrackPesist

            -- 启动本轮 track 的 "瞬移"
            cs_coroutine.yield_return( self.uiRole:RoleTeleporting( trackPesist, false ))

            -- 开始播放 role 走路 音效: 
            Maze2DSounds.PlayMusic( Maze2DSounds.musics.ui_festival_map_walk )

            -- 沿着一条又一条 track 运动:

            while (self.tgtTrackNodeGO ~= self.lastTrackNodeGO) and (self.isRoleMoving == true) do 
                -- 若 role 移动到本条 track 的 end, isRoleMoving 会被改写为 false;

                -- 后2参数是 ref 修饰:
                self.uiRole:RolePivotTF().position,self.move_t,self.isRoleMoving = self.trackBrain:CalcTrackMovePos( self.lastTrackNodeGO, self.nextTrackNodeGO, moveSpeed, self.move_t, self.isRoleMoving )
                assert( type(self.move_t) == "number" )
                assert( type(self.isRoleMoving) == "boolean" )

                if self.isRoleMoving == false then
                                
                    -- 先结束本轮 track 的 "瞬移"
                    cs_coroutine.yield_return( self.uiRole:RoleTeleporting( trackPesist, true ))
                    self.last2TrackNodeGO = self.lastTrackNodeGO
                    self.lastTrackNodeGO = self.nextTrackNodeGO

                    -- 在 nextTrackNodeGO 位置发现 bubble (意味着此处存在 迷宫事件), 登记这个 迷宫事件, 并立即打断后续所有移动
                    if self:CheckThisTrackNodeGO( self.nextTrackNodeGO, self.nextTrackNodeGO == self.tgtTrackNodeGO ) == true then
                        break
                    end

                    -- 若存在下一段 track, 则准备进入下一段移动
                    if self.nextTrackNodeGO ~= self.tgtTrackNodeGO then
                        self.nextTrackNodeGO = self.nextTrackNodeGO.nextTrackNodeGO
                        self.isRoleMoving = true
                        self.move_t = 0.0
                        
                        -- 若需要, 启动下一轮 track 的 "瞬移"
                        if self.lastTrackNodeGO ~= self.nextTrackNodeGO  then

                            trackPesist = self.trackBrain:FindTrackPesistInData( self.lastTrackNodeGO, self.nextTrackNodeGO )
                            --cs_coroutine.yield_return( self.uiRole:RoleTeleporting( trackPesist, false ))
                            self.uiRole:RoleTeleporting( trackPesist, false )
                        end
                    end
                end
                -- cameraPivot 还是要继续跟随 role 的, 只是跟随得更紧密了;
                self.cameraPivot.position = Vector3.Lerp( self.cameraPivot.position, self.mazeInput:CalcSafetyPos( self.uiRole:RoleTFPos()), 0.5 )

                coroutine.yield(Yielders.EndOfFrame)
            end

        end
    end

    -- 停止播放 role 走路 音效: 
    Maze2DSounds.Stop( Maze2DSounds.musics.ui_festival_map_walk )

    -- ------ 移动到目的地后, 需要做的事 --------:
    -- 离开某个 gear bubble 后, 要让它恢复点亮
    self:ShowGearBubbleWhenLeaveGear( self.lastTrackNodeGO.id )
    --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl - 1  -- !!!!!! MUST
    Maze2DStates.MinusIsInAutoControl() -- !!! Must 

    print( "koko -- 处理 bubble 结束:  MazeMain:WhenHitTrackNodeGOOrBubble -2-" )
end



-- ret: 若发现这个 tracknodego 上存在对应的 bubble, 就应该停止整个移动流程, 开始处理这个 bubble
---@param trackNodeGO TrackNodeGO
---@param isLastTrackNodeGO boolean
---@return boolean
function MazeMain:CheckThisTrackNodeGO( trackNodeGO, isLastTrackNodeGO )

    local bubble = self.tmpBubbles[trackNodeGO.id]
    if not isNull(bubble) then

        -- 允许 role 穿过 gear bubble 节点;
        if isLastTrackNodeGO == false and bubble.eventType == MazeEventType.Get().Gear then
            return false
        end

        -- --1-- 只能通过 role 的移动来触发, 需要 --2-- 的补充才完善;
        self.isInGear = false 
        -- 暂存这个需求, 返回退出本函数, 且直接中断整个移动
        -- 等到下一帧, 再来处理这个暂存的 迷宫事件;
        self:AddToCatchedEventKeys( EventKey.New({id=bubble.id, type=bubble.eventType}) )
        return true
    end
    
    -- 哑节点 (id < 0 的那些) 是不应该触发 isInGear 状态变化的;
    if trackNodeGO.id >= 0 then
        -- --1-- 只能通过 role 的移动来触发, 需要 --2-- 的补充才完善;
        self.isInGear = false 
    end

    return false
end 


-- 执行配表中的第一个事件; (若存在连续事件, 则一直执行)
---@return System.Collections.IEnumerator
function MazeMain:RunFirstEvent()
    print( "不读取存档, 从头开始迷宫, RunFirstEvent()" )
    -- 从现在起, 玩家的输入 就暂时被迷宫屏蔽了;

    local eventData = self.handleMazeTableFile.eventDatas[self.handleMazeTableFile.startEventKey.keyStr] -- EventData
    cs_coroutine.yield_return(self:RunOneEvent( eventData, Maze2DStates.isFindNewMap, true ))

end



-- catchedEventKeys
---@return System.Collections.IEnumerator
function MazeMain:RunCatchedEvents()
    -- 从现在起, 玩家的输入 就暂时被迷宫屏蔽了;

    Maze2DStates.AddIsInAutoControl() -- !!! Must 

    -- 确保一定能释放 isInAutoControl:
    xTry(function()
        
        while #self.catchedEventKeys > 0 do
            local key = self.catchedEventKeys[1] -- EventKey
            table.remove( self.catchedEventKeys, 1 )
            local eventData = self.handleMazeTableFile.eventDatas[key.keyStr] -- EventData
            cs_coroutine.yield_return(self:RunOneEvent( eventData ))
        end
        ---
        Maze2DStates.MinusIsInAutoControl() -- !!! Must 

    end, function()
        Maze2DStates.MinusIsInAutoControl() -- !!! Must 
        printError("koko %s", debug.traceback());
    end)

end 


-- 当 role 踩在 gear 节点上, 然后按下解谜按钮时(比如旋转位移按钮), 触发的事件
---@return System.Collections.IEnumerator
function MazeMain:RunPuzzleCallBack()
    -- 从现在起, 玩家的输入 就暂时被迷宫屏蔽了;

    Maze2DStates.AddIsInAutoControl() -- !!! Must 
    
    -- 确保一定能释放 isInAutoControl:
    xTry(function()
        cs_coroutine.yield_return(self.HandleMazeGear( self.puzzleSelf )) -- 只是个 函数指针, 不是方法
        Maze2DStates.MinusIsInAutoControl() -- !!! Must 

    end, function()
        Maze2DStates.MinusIsInAutoControl() -- !!! Must 
        printError("%s", debug.traceback());
    end)
    
end


-- 读取游戏存档
---@return System.Collections.IEnumerator
function MazeMain:ReadSavedData()
    print(" ==== 读取存档, 还原开始 ====")
    assert( not isNull(Maze2DStates.mapDecryptionHomeDatas.playerMapQuestInfo.eventInfo) )
    assert( not isNull(Maze2DStates.mapDecryptionHomeDatas.playerMapQuestInfo.puzzleData) )

    -- ==========================:
    -- 有些谜题需要存储特殊数据
    if not isNull(self.ReadSavedDataToPuzzle) then
        self.ReadSavedDataToPuzzle(self.puzzleSelf, Maze2DStates.mapDecryptionHomeDatas.playerMapQuestInfo.puzzleData ) -- 调用函数指针, 不是方法
    end

    -- ==========================:
    local allEventKeys = {}
    local tmpBubbleKeys = {} -- new HashSet<EventKey>( new EventKeyEqualityComparer()) -> <eventKey.keyStr, eventKey>
    local lightRooms_inn = {} -- HashSet<string> -> <string,int>
    local customJobTagsWhenAftar = {} -- string[] table 

    for i,kStr in pairs(Maze2DStates.mapDecryptionHomeDatas.playerMapQuestInfo.eventInfo) do

        local eventKey = EventKey.New({keyStr=kStr}) -- EventKey
        table.insert( allEventKeys, eventKey )

        assert( not isNull(self.handleMazeTableFile.eventDatas[eventKey.keyStr]), "没找到: "..eventKey.keyStr )
        local eventData = self.handleMazeTableFile.eventDatas[eventKey.keyStr] -- EventData

        --  删除本 bubble:
        for kStr2,k in pairs(tmpBubbleKeys) do 
            if kStr2 == eventData.eventKey.keyStr then 
                tmpBubbleKeys[kStr2] = nil  -- Dic.Remove() 
            end
        end
        -- 熄灭要熄灭的 房间
        for i2, roomKey in pairs(eventData.disappearedRoomsWhenEnd) do
            if not isNull(lightRooms_inn[roomKey]) then -- 允许被多次熄灭
                --table.remove( lightRooms_inn, roomKey )
                lightRooms_inn[roomKey] = nil
            end
        end
        --  点亮要点亮的房间
        for i2, roomKey in pairs(eventData.showedRoomsWhenEnd) do -- roomKey:string
            --print("点亮的room: " .. roomKey)
            if isNull(lightRooms_inn[roomKey]) then -- 允许被重复写入
                lightRooms_inn[roomKey] = 1 -- Dic.Add(), value 随意
            end
        end
        --  登记 本次事件后 要出现的 气泡
        for i2,k in pairs(eventData.showedEventsWhenEnd) do -- k:EventKey
            if MazeEventType.IsHaveUIPrefab(k.eventType) == true  then
                -- 解谜成功后, 不显示任何 gear bubble:
                if      (not isNull(self.IsPuzzleBeSolved)) and (self.IsPuzzleBeSolved(self.puzzleSelf) == true) -- 函数指针
                    and (k.eventType == MazeEventType.Get().Gear) 
                then
                    goto continue
                end

                -- 有些 event 不能在 读档加载时被登记:
                local eData = self.handleMazeTableFile.eventDatas[k.keyStr] -- EventData

                if (eData.skipTagWhenReload ~= "") and (not isNull(self.IsSkipWhenReload)) 
                    and (self.IsSkipWhenReload(self.puzzleSelf, eData.skipTagWhenReload) == true) -- 函数指针
                then 
                    goto continue
                end

                tmpBubbleKeys[k.keyStr] = k -- Dic.Add()

                :: continue ::
            end
        end
        --  暂存所有 customJobTagWhenAfter:
        if eventData.customJobTagWhenAfter~="" then 
            table.insert(customJobTagsWhenAftar, eventData.customJobTagWhenAfter ) -- 暂时不关心是否重复了
        end

        --  自动执行的事件不用处理, 因为它一定会被自动执行;
    end

    -- -- ==========================:
    -- -- 把数据打印一下:
    -- -- string ss = "还原后的数据: \n lightRooms_inn: ";
    -- foreach( var k in lightRooms_inn ) 
    -- {
    --     ss += k + ",  ";
    -- }
    -- ss += "\ntmpBubbleKeys: ";
    -- foreach( var e in tmpBubbleKeys ) 
    -- {
    --     ss += "    \n" + e.keyStr;
    -- }
    -- ss += "\n\n ==================== \n\n";
    -- Debug.LogWarning(ss);

    -- ==========================:
    for roomKey,v in pairs(lightRooms_inn) do
        -- -1- 点亮房间
        self:ControlRoomLight( roomKey, true )
        -- -2- 点亮所有 tracknodegos;
        local roomIds = self.handleMazeTableFile.IDsInRooms[roomKey] -- List<int> table
        assert( isTable(roomIds) )
        for m,id in pairs(roomIds) do
            local trackNodeGO = self.trackBrain:FindTrackNodeGO(id) -- TrackNodeGO
            trackNodeGO:Display()
        end
    end
    -- 点亮房间后 人为停顿下:
    cs_coroutine.yield_return( Maze2DStates.Wait_0D8_Seconds )

    -- ==========================:
    -- 只有这个 trakNode 在配表里设置了 customJobTagWhenAfter 值, 此处才会被触发
    for i,tag in pairs(customJobTagsWhenAftar) do -- tag:string
        assert( self.CustomJobWhenAfter )
        cs_coroutine.yield_return(self.CustomJobWhenAfter( self.puzzleSelf, tag )) -- 函数指针
    end
    -- ==========================:
    for kStr,k in pairs(tmpBubbleKeys) do
        cs_coroutine.yield_return(self:ShowNewEventWhenEnd( k ))
    end

    -- ==========================:
    -- 会被自动触发的事件:
    local newAutoKeys = self.handleMazeTableFile:FindReliantEventKeysFromPreconditionDict( allEventKeys )
    for i,k in pairs(newAutoKeys) do
        local ed = self.handleMazeTableFile.eventDatas[k.keyStr]
        --print( "tpr == 执行 前置依赖事件: " .. k.keyStr )
        cs_coroutine.yield_return(self:RunOneEvent( ed )) -- !!! 递归
    end

end





-- !!! ===================================================================== !!! --
-- !!! 要保证本函数是 一个 eventData 的 唯一执行口;
---@param eventData EventData
---@param isFirstIntoThisMap_   boolean -- 可为 nil
---@param isWaitAfterShowRooms_ boolean -- 可为 nil
---@return System.Collections.IEnumerator
function MazeMain:RunOneEvent( eventData, isFirstIntoThisMap_, isWaitAfterShowRooms_ )

    --print( "koko -- RunOneEvent -- isInAutoControl = " .. Maze2DStates.isInAutoControl )

    -- !!! 补丁, 约束 isInAutoControl: 
    if Maze2DStates.isInAutoControl ~= 1 then 
        printError( "异常 isInAutoControl (1) = " .. tostring(Maze2DStates.isInAutoControl) )
        Maze2DStates.isInAutoControl = 1 -- !!!!! 强制写 1;  保证不会出现上下浮动
    end

    local eventKey = eventData.eventKey
    
    if not (    eventKey.eventType == MazeEventType.Get().Gear    -- gear bubble 不会被直接删除掉;
            or  eventKey.eventType == MazeEventType.Get().Battle  -- battle bubble 要延迟到 EnterBattle() 被隐藏
            or  eventKey.eventType == MazeEventType.Get().Boss    -- battle bubble 要延迟到 EnterBattle() 被隐藏
        )
    then
        self:HideBubble( eventKey.id )
    end


    -- 处理 gear bubble 必备的 准备工作:
    if( eventKey.eventType == MazeEventType.Get().Gear ) then
        self.isInGear = true
        if not isNull(self.WhenEnterGear)  then

            -- 在一个章节游玩中, 第一次进入 gear 会主动弹出 解谜提示面板:
            if self.isShowTipsPopup == false then 
                self.isShowTipsPopup = true 
                cs_coroutine.yield_return( MazeMainUI.GetCurrentInstance():Open_TipsPopup_AndWait() )
            end

            self.WhenEnterGear( self.puzzleSelf, eventKey ) -- 函数指针
        end
        -- 让本位置的 bubble 消失, 让别的位置的 bubble 显示;
        self:HideCurrentGearBubble( eventKey.id )
        return  --yield break; // 直接退出了

    elseif eventKey.eventType == MazeEventType.Get().PuzzleCustom  then
        -- 让 puzzle 来执行一部分功能
        assert( not isNull(self.PuzzleCustomFunc) )
        self.PuzzleCustomFunc(self.puzzleSelf, eventKey.keyStr) -- 函数指针

    else 
        -- --2--  MUST !!!: 因为有些事件是直接在 谜题内被触发的, 比如 迷宫2 中的, 
        -- 此时无法依赖 --1-- 位置的设置来让 isInGear 变为 false;
        self.isInGear = false
    end

    -- =========================  ===========================
    self.isCurrentEventBeStopped = true

    -- 执行这个事件的本体:
    cs_coroutine.yield_return(self:HandleMazeEvent( eventKey ))

    -- 战斗未成功, 在此中止, 直到玩家战斗胜利为止;
    if self.isCurrentEventBeStopped == true then 
        return
    end     

    -- pazzle自定义事件(after), 比如 地球仪下降, 荷叶移动成路线 等:
    if not isNull(eventData.customJobTagWhenAfter) and eventData.customJobTagWhenAfter ~= "" then
        assert( self.CustomJobWhenAfter )
        cs_coroutine.yield_return(self.CustomJobWhenAfter( self.puzzleSelf, eventData.customJobTagWhenAfter )) -- 函数指针
    end


    -- 结束后要消失的房间 (熄灭 trackNodes)
    self:HideRoomsWhenEnd( eventData )
    -- 结束后要点亮的房间 (显示 trackNodes)
    self:ShowNewRoomsWhenEnd( eventData )

    -- 当第一次进入本 map 时, 需要显示一个 大横栏:
    if isFirstIntoThisMap_ == true then 
        cs_coroutine.yield_return( self:OpenDialogEventResultPopup( Maze2DStates.mapId, EventResult.FindMap) )
    end 

    -- 在某些情况下, 点亮房间后需要停顿一下:
    if isWaitAfterShowRooms_ == true then 
        cs_coroutine.yield_return( Maze2DStates.Wait_0D4_Seconds )
    end

    -- 结束后要显示的事件 (点亮 bubble): 同时让相机 对准这些要被点亮的 bubble
    cs_coroutine.yield_return(self:ShowNewEventsWhenEnd( eventData ))

    -- !!! 二次保证:
    -- !!! 事实证明这里确实出现过异常, 每当从迷宫退出时, 这里的 isInAutoControl 为 0; 但这种情况是正常的...
    if Maze2DStates.isInAutoControl ~= 1 then 
        printError( "异常 isInAutoControl (2) = " .. tostring(Maze2DStates.isInAutoControl) )
        Maze2DStates.isInAutoControl = 1 -- !!!!! 强制写 1;  保证不会出现上下浮动
    end

    -- 某些事件的 前置依赖事件被完成后, 这些新事件需要被自动执行:
    -- newAutoKeys: List<EventKey> table
    local newAutoKeys = self.handleMazeTableFile:FindReliantEventKeysFromPreconditionDict( {eventData.eventKey} )
    for i,k in pairs(newAutoKeys) do
        local ed = self.handleMazeTableFile.eventDatas[k.keyStr]
        --print( "tpr == 执行 前置依赖事件: " .. k.keyStr )
        cs_coroutine.yield_return(self:RunOneEvent( ed )) -- !!! 递归
    end
end




-- todo: 为了让 puzzle class 能调用, 暂时做成 public 的; (目前仅被 迷宫2 调用过)
---@param eventKey EventKey
---@return System.Collections.IEnumerator
function MazeMain:HandleMazeEvent(eventKey)
    print("正式处理 eventKey: " .. eventKey.keyStr )

    local eventData = self.handleMazeTableFile.eventDatas[eventKey.keyStr] -- EventData
    self.isCurrentEventBeStopped = false

    --cs_coroutine.yield_return( Maze2DStates.Wait_0D2_Seconds )

    -- 如果是战斗, 则要接入战斗: 
    if      eventKey.eventType == MazeEventType.Get().Boss   
        or  eventKey.eventType == MazeEventType.Get().Battle
    then 
        cs_coroutine.yield_return( self:EnterBattle(eventData) )

        -- 不管战斗有没有赢, 都要及时释放这个 函数指针
        --Maze2DStates.CallServerRecordMapWhenBattleWin = nil -- 立刻释放

        GameUtils.SetUICameraProjection(true) -- ui相机 设为正交 (因为现在战斗中是透视模式)

        -- 每个迷宫第一章节的 boss战之后, 需要大横栏:
        if      Maze2DStates.isBattleWin == true
            and eventKey.eventType == MazeEventType.Get().Boss
            and eventData.customInfo == "firstboss" 
        then 
            cs_coroutine.yield_return( self:OpenDialogEventResultPopup( self.unlockTrackQuestRefId, EventResult.UnlockTrackQuest) )
        end 

        -- 刷新 红三栏 数据:
        MazeMainUI.GetCurrentInstance():RefreshRedThreeTextDatas( false ) -- 战斗不需要再调用后端 home 了

        cs_coroutine.yield_return( Maze2DStates.Wait_0D5_Seconds )
        -- 如果战斗失败, 主流程将被卡在本 trackNode, 不能自动弹出后续 trackNode
        self.isCurrentEventBeStopped = (Maze2DStates.isBattleWin == false)
        

    -- 播放剧情 Plot: 
    elseif eventKey.eventType == MazeEventType.Get().Plot then 
        cs_coroutine.yield_return( self:PlayStory( eventData.storyId, eventData.isStoryHasBG ) )
        cs_coroutine.yield_return( self:CallServerRecordMap(eventData) ) -- !!! 后端存档

        -- 刷新 红三栏 数据:
        --MazeMainUI.GetCurrentInstance():RefreshRedThreeTextDatas( true ) 

        cs_coroutine.yield_return( Maze2DStates.Wait_0D5_Seconds )

    -- 开宝箱:
    elseif eventKey.eventType == MazeEventType.Get().Chest then 
        assert( not isNull( self.chests[eventKey.keyStr]) )

        -- 必须要先调用后端 recordMap() 保存本节点, 顺带拿到 宝箱数据, 然后才能处理 chest 事件:
        cs_coroutine.yield_return( self:CallServerRecordMap(eventData) ) -- !!! 后端存档
        assert( self.RewardsFromServer ~= nil ) -- CallServerRecordMap() 中填充的
   
        self.isRewardDialogClosed = false -- 先把状态值初始化

        -- 领取宝箱数据, 
        GoodsUtils.DrawRewards( self.RewardsFromServer )

        -- 刷新 红三栏 数据:
        MazeMainUI.GetCurrentInstance():RefreshRedThreeTextDatas( true )  

        -- 播放窗口动画:
        UIModule.OpenDialog({ 
            id = Constants.UITypeIds.UICommonRewardPop, 
            parameters = { rewards = self.RewardsFromServer } 
        })
        --
        self.chests[eventKey.keyStr]:SetActive( false ) -- 粗暴地熄灭...
        -- 等待 奖励窗口被关闭:
        while self.isRewardDialogClosed == false do 
            coroutine.yield(Yielders.EndOfFrame)
        end 

        -- 每个迷宫第一章节的 boss战后 "宝箱", 领取后会触发 横栏:
        if eventData.customInfo == "firstchest" then 
            cs_coroutine.yield_return( self:OpenDialogEventResultPopup( eventData.reward, EventResult.FindAntique) )
        end 

        -- 等待一会儿:
        cs_coroutine.yield_return( Maze2DStates.Wait_0D5_Seconds )
        -- 可能存在的剧情: 
        if eventData.rewardStory ~= nil then 
            cs_coroutine.yield_return( self:PlayStory( eventData.rewardStory, eventData.isStoryHasBG ) )
            -- 等待一会儿:
            cs_coroutine.yield_return( Maze2DStates.Wait_0D5_Seconds )
        end 
    

    elseif eventKey.eventType == MazeEventType.Get().End then 
        -- print("tpr -- End 开始等待")
        -- cs_coroutine.yield_return(Yielders.GetWaitForSeconds(4))
        -- print("tpr -- End 结束等待")

        -- 只要不是本迷宫的最后一章节, 都需显示特殊的 大横栏:
        if Maze2DStates.isInLastGroup == false then 
            local stage = (checkInt(Maze2DStates.groupId) % 10) -- int: 1,2,3
            cs_coroutine.yield_return( self:OpenDialogEventResultPopup( Maze2DStates.mapId, EventResult.CompleteMapExploration, stage ) )
        end 

        cs_coroutine.yield_return( self:CallServerRecordMap(eventData) ) -- !!! 后端存档
        cs_coroutine.yield_return( self:CallServerQuitMap() )
        print("tpr -- 本章节结束, 退出 2D迷宫 =============================== --")
        MapDecryptionUtils.QuitMaze() -- 退出 2D迷宫场景

    else 
        cs_coroutine.yield_return( self:CallServerRecordMap(eventData) ) -- !!! 后端存档

        -- 刷新 红三栏 数据:
        --MazeMainUI.GetCurrentInstance():RefreshRedThreeTextDatas( true ) 
    end
end



-- 领取宝箱界面被关闭后, 会触发此 callback: 
function MazeMain:OnEventCloseRewardDialogListener()
    self.isRewardDialogClosed = true
end 



function MazeMain:EnterBattle( eventData )

    assert( not isNull(eventData.battleID) ) -- 确保配表数据正确


    -- !!! 手动强制设置 (这么写很脏, 但是时间有限先这么干,  目的就是等 从战斗/战斗选择界面返回时, 会再次点亮 2D UI Dialog, 此时会把这个变量设 true)
    Maze2DStates.isMazeMainUIOpen = false 


    Maze2DStates.isBattleWin = false -- 先把状态值清空; 只有等战斗胜利后, 它才会被设为 true

    -- 提前准备好 战斗胜利时的存档函数
    -- 战斗胜利的一瞬间要立即存档, 否则玩家会抓住这个漏洞, 反复打这场战斗
    Maze2DStates.CallServerRecordMapWhenBattleWin = function()
        cs_coroutine.start( self.CallServerRecordMap, self, eventData, function()
            Maze2DStates.isBattleWin = true
            --printError( "koko 战斗胜利 -2-" )
        end)
    end 

    -- ============================= 进入战斗 队伍选关 ====================================
    local questId      = eventData.battleID -- 12140101   这个就是 迷宫配表里的 regionId
    local activityUUid = MapDecryptionMgr:GetActivityUUId() -- 389  活动id

    MapDecryptionUtils.EnterTeamChoose(
        questId, 
        activityUUid, 
        {
            UIArgs(MapDecryptionUtils.GetDialogId(MapDecryptionUtils.DialogType.Maze2D)) -- 从队伍界面退出时, 要回退到 2D UI 界面
        }
    )
    --KCookie.Set( MapDecryptionConstants.EventNames.TrackQuestId, questId)
    KCookie.Set( MapDecryptionConstants.EventNames.ExploreMapId, Maze2DStates.mapId)

    -- ============================== 
    -- 进入 队伍选择 界面后, 立刻就执行下方代码...

    -- 等待从战斗中返回, 再次打开 2D迷宫的 ui dialog
    cs_coroutine.yield_return( Maze2DStates.Wait_0D5_Seconds )
    while true do 
        if Maze2DStates.isMazeMainUIOpen == true then
            --printError( "从战斗等待中归来;  再次打开 2D迷宫的 ui dialog" )
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
        coroutine.yield(Yielders.EndOfFrame)
    end 
    coroutine.yield(Yielders.EndOfFrame)

    -- 恢复播放 bgm 音乐: 
    Maze2DSounds.PlayMusic( Maze2DSounds.musics.bgm_festival_map )

    -- 不管战斗有没有赢, 都要及时释放这个 函数指针
    Maze2DStates.CallServerRecordMapWhenBattleWin = nil -- 立刻释放

    -- 刷新 红三栏 数据:
    MazeMainUI.GetCurrentInstance():RefreshRedThreeTextDatas( true )

    -- 检查 战斗结果
    if Maze2DStates.isBattleWin == true then 
        self:HideBubble( eventData.eventKey.id )
    else 
        -- 如果战斗失败, 主角需要 回退到上一个 trackNode
        self.lastTrackNodeGO = self.last2TrackNodeGO
        --self.uiRole:RolePivotTF().position = self.last2TrackNodeGO.pos
        self.uiRole:SetRolePosImmediately( self.last2TrackNodeGO.pos )
        self.cameraPivot.position = self.mazeInput:CalcSafetyPos( self.uiRole:RolePivotTF().position )
    end 
end




---@param trackNodeGOID integer -- 比如: 2.1 
---@return void
function MazeMain:HideBubble( trackNodeGOID )
    local bubble = self.tmpBubbles[trackNodeGOID]
    if not isNull(bubble) then
        Object.Destroy( bubble.gameObj ) -- 先粗暴地删除之
        self.tmpBubbles[trackNodeGOID] = nil -- Dic.Remove()
    end 
    -- todo: "万一没有 bubble 时该怎么处理"  暂时不关心这个问题...
end



function MazeMain:PlayStory( storyId_, isStoryHasBG_ )
    assert( storyId_ ~= nil )


    --self.roleCanvas.enabled = false
    self.uiRole:SetIsShow( false )
    self.bubbleCanvas.enabled = false
    self.trackBrain:TmpHideAllVisibleTrackNodeGOs()

    local isChapterFinish = false
 
    ChapterUtils.ProcessChapter( storyId_, function(go)
            -- self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
            -- CS.UINavigationBarRoot.Instance:SetActive(false)
            -- comp:SetEnterEndStoryId()
            self._plotGo = go
        end, 
        function()
            --self.roleCanvas.enabled = true
            self.uiRole:SetIsShow( true )
            self.bubbleCanvas.enabled = true
            self.trackBrain:RestoreVisibleTrackNodeGOs()

            KTool.SafeDelete(self._plotGo)
            -- self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            -- CS.UINavigationBarRoot.Instance:SetActive(true)
            isChapterFinish = true
        end,
        {
            useRealBg = isStoryHasBG_ ~= true 
        }
    )

    -- 等待剧情被播完:
    while isChapterFinish == false do
        coroutine.yield(Yielders.EndOfFrame)
    end

    -- 恢复播放 迷宫 bgm: 
    Maze2DSounds.PlayMusic( Maze2DSounds.musics.bgm_festival_map )
end 


-- -- 调用后端 ActivityMapDecryption/recordMap（保存地图信息)
-- -- 保存单个节点 (bubble) 的信息, 如果是 chest bubble, 则能拿到奖励信息: rewards
function MazeMain:CallServerRecordMap( eventData, callbackWhenFinish_ )
    local eventKey = eventData.eventKey
    -- !!!!! Save:
    if isUseSavedData == true and eventData.isSupportSave == true then 
        -- 从后端读取 关键节点 (带 bubble 的) 的数据 :
        local puzzleData_ = "_"
        if not isNull(self.SaveDataFromPuzzle) then
            puzzleData_ = self.SaveDataFromPuzzle(self.puzzleSelf) -- 函数指针
        end 

        self.RewardsFromServer = nil

        Maze2DStates.quitWaitFrames = 120 -- !!! 锁: 返回键

        UIRaycastBlocker:AddCondition("MapDecryptionExplorePanel.recordMap")    
        self:CollectCoroutineRets( cs_coroutine.start(function()
            UIRaycastBlocker:RemoveCondition("MapDecryptionExplorePanel.recordMap")

            ---@type ActivityDojo
            local activityData = self.mapDecryptionComponent:GetActivityData()
            
            GameUtils.Request(
                Interfaces.ActivityMapDecryptionRecordMap, 
                {
                    activityUuid = activityData.id,
                    event = eventKey.keyStr,
                    puzzleData = puzzleData_
                }, 
                function(request, response)
                    if checkNumber(response.errCode) ~= 0 then 
                        printError( "没读取到 后端数据 RecordMap - 3 -" )
                        return 
                    end
                    ----
                    assert( response.data ~= nil )
                    assert( response.data.rewards ~= nil ) -- 是个 list
                    self.RewardsFromServer = response.data.rewards
                end
            )
        end))
        ---
        local waitFrames = 0
        while self.RewardsFromServer == nil do 
            waitFrames = waitFrames + 1
            if waitFrames > 120 then 
                -- 如果等了两秒依然没有等到 写后端结束, 也释放
                Maze2DStates.quitWaitFrames = -1 -- !!! 释放: 返回键
            end
            coroutine.yield(Yielders.EndOfFrame)
        end 

        Maze2DStates.quitWaitFrames = -1 -- !!! 释放: 返回键

        if not isNull(callbackWhenFinish_) then
            callbackWhenFinish_()
        end
    end 
end



-- 调用后端 ActivityMapDecryption/quitMap（退出地图)
function MazeMain:CallServerQuitMap( eventKey )

    local isRet = false

    UIRaycastBlocker:AddCondition("MapDecryptionExplorePanel.quitMap")    
    self:CollectCoroutineRets( cs_coroutine.start(function()
        UIRaycastBlocker:RemoveCondition("MapDecryptionExplorePanel.quitMap")

        ---@type ActivityDojo
        local activityData = self.mapDecryptionComponent:GetActivityData()

        -- 不可能在此处卡死了, 故不修改 quitWaitFrames;
        
        GameUtils.Request(
            Interfaces.ActivityMapDecryptionQuitMap, 
            {
                activityUuid = activityData.id,
            }, 
            function(request, response)
                if checkNumber(response.errCode) ~= 0 then 
                    printError( "没读取到 后端数据 ActivityMapDecryption/quitMap " )
                    return 
                end
                ----
                isRet = true
            end
        )
    end))
    ---
    while isRet == false do
        coroutine.yield(Yielders.EndOfFrame)
    end
end




-- 结束后要点亮的事件 (点亮 bubble) (可能有若干个):
---@param eventData EventData
---@return System.Collections.IEnumerator
function MazeMain:ShowNewEventsWhenEnd(eventData)
    for i,eventKey in pairs(eventData.showedEventsWhenEnd) do
        cs_coroutine.yield_return(self:ShowNewEventWhenEnd( eventKey ))
    end
end



-- 点亮单个 bubble:
---@param eventKey EventKey
---@return System.Collections.IEnumerator
function MazeMain:ShowNewEventWhenEnd(eventKey)

    local trackNodeGO = self.trackBrain:FindTrackNodeGO( eventKey.id ) -- TrackNodeGO
    local tgtPos = trackNodeGO.pos -- Vector3

    cs_coroutine.yield_return( Maze2DStates.Wait_0D1_Seconds ) -- 强行停顿下;
    
    -- 将 cameraPivot 对齐 tgtPos:
    cs_coroutine.yield_return(MazeMain.MoveTo2( self.cameraPivot, self.mazeInput:CalcSafetyPos(tgtPos), {smoothTime = 0.22, maxSpeed = 30.0} ))

    trackNodeGO:Display()

    if MazeEventType.IsHaveUIPrefab(eventKey.eventType) == true  then
        local newgo,bubble = self:CreateNewUIBubble(eventKey, self.bubbleCanvas, trackNodeGO, eventKey.eventType ) -- Gameobj, out MazeUI_Bubble
        self.tmpBubbles[eventKey.id] = bubble -- 登记

        -- chest bubble 需要特殊点亮:
        if eventKey.eventType == MazeEventType.Get().Chest then 
            assert( not isNull( self.chests[eventKey.keyStr] ) )
            self.chests[eventKey.keyStr]:SetActive( true ) -- 粗暴地点亮...
        end
    end
end


-- 结束后要熄灭的房间:
---@param eventData EventData
---@return void
function MazeMain:HideRoomsWhenEnd(eventData)

    for i,roomKey in pairs(eventData.disappearedRoomsWhenEnd) do
 
        -- -1- 熄灭房间
        self:ControlRoomLight( roomKey, false )
        
        -- -2- 熄灭此房间内的 所有 tracknodegos;
        local roomIds = self.handleMazeTableFile.IDsInRooms[roomKey]
        assert( isTable(roomIds) )
        for i,id in pairs(roomIds) do
            local trackNodeGO = self.trackBrain:FindTrackNodeGO(id)
            trackNodeGO:Hide()
        end
    end
end



-- 结束后要点亮的房间 和 tracknodegos:
---@param eventData EventData
---@return void
function MazeMain:ShowNewRoomsWhenEnd(eventData)

    for i,roomKey in pairs(eventData.showedRoomsWhenEnd) do

        -- -1- 点亮房间
        self:ControlRoomLight( roomKey, true )
        
        -- -2- 点亮所有 tracknodegos;
        local roomIds = self.handleMazeTableFile.IDsInRooms[roomKey]
        assert( isTable(roomIds) )
        for i,id in pairs(roomIds) do
            local trackNodeGO = self.trackBrain:FindTrackNodeGO(id)
            trackNodeGO:Display()
        end
    end
end



---@param canvas UnityEngine.Canvas
---@param eventKey EventKey
---@param trackNodeGO TrackNodeGO
---@param eventType MazeEventType
---@return UnityEngine.GameObject, MazeUI_Bubble @ MazeUI_Bubble bubble
function MazeMain:CreateNewUIBubble( eventKey, canvas, trackNodeGO, eventType)

    local prefab = self:ChooseUIBubblePrefab(eventType) -- GameObject
    local newPos = trackNodeGO.pos + Vector3( 0.0, 0.2, 0.2 ) -- z: 高度, 因为目前的 bubble 尺寸很小, 还是要设置的靠近一点才行...

    -- !!!!! 未来改成 pool 
    local newgo = Object.Instantiate(
        prefab,
        newPos,
        Quaternion.Euler( 90.0,0.0,0.0 ),
        canvas.transform
    )

    -- battle/boss 指定 角色图片:
    if eventType == MazeEventType.Get().Battle or eventType == MazeEventType.Get().Boss then
        
        local idComps = newgo:GetComponentsInChildren(typeof(IDComp),true) -- 包含自己, Array
        local isFind = false
        for i=0, idComps.Length-1 do
            local idComp = idComps[i] -- ID component
            if idComp.stringId == "Icon" then 
                isFind = true

                local rawImage = KTool.GetComponent(idComp.gameObject, typeof(RawImage))
                assert( rawImage )

                local eventData = self.handleMazeTableFile.eventDatas[eventKey.keyStr] -- EventData 
                local texture = self.iconTextures[eventData.iconPath]
                assert( not isNull (texture) )
                rawImage.texture = texture

            end
        end
        assert( isFind, "battle,boss prefab 配置出错..." )
    end


    -- 有些 bubble 出现时 需要发出声音:
    if eventType == MazeEventType.Get().Chest then
        Maze2DSounds.PlayMusic( Maze2DSounds.musics.ui_festival_map_box )
    elseif eventType == MazeEventType.Get().Boss then
        Maze2DSounds.PlayMusic( Maze2DSounds.musics.ui_festival_map_boss ) 
    else 
        Maze2DSounds.PlayMusic( Maze2DSounds.musics.ui_festival_map_bubble ) 
    end

    -- 通过 ID comp 来确认 Bubble ui go
    local idComp = KTool.GetComponent(newgo, typeof(IDComp)) -- IDComp
    assert( not isNull(idComp), "prefab 文件缺少 ID 组件" )

    local bubbleStr = MazeUI_Bubble.ToString( trackNodeGO.id, eventType )
    idComp.id = MazeUI_Bubble.GetTypeID() -- 类型标识
    idComp.stringId = bubbleStr -- 存储的信息本体


    ---@type Engine.Modules.LuaBehaviour
    local bubbleComp = KTool.GetComponent(newgo, typeof(LuaBehaviour)).Env -- 
    assert( bubbleComp, "没绑定 MazeUI_Bubble LuaBehaviour" )
    bubbleComp:SelfInit( bubbleStr )

    return newgo, bubbleComp
end




---@param eventType MazeEventType
---@return UnityEngine.GameObject
function MazeMain:ChooseUIBubblePrefab(eventType)

    -- if     eventType == MazeEventType.Get().Story then
    --     return self.UIPlotPrefab
    if eventType == MazeEventType.Get().Plot then
        return self.UIPlotPrefab
    elseif eventType == MazeEventType.Get().Gear then
        return self.UIGearPrefab
    elseif eventType == MazeEventType.Get().Battle then
        return self.UIBattlePrefab
    elseif eventType == MazeEventType.Get().Boss then
        return self.UIBossPrefab
    elseif eventType == MazeEventType.Get().Chest then
        return self.UIChestPrefab
    else 
        printError("代码存在漏洞, 参数不支持")
        assert(false)
        return nil
    end
end





