-- 第三版 MoveTo, 改用 SmoothDamp;
-- ---@param be Transform
-- ---@param tgtPos Vector3
-- ---@return System.Collections.IEnumerator
function MazeMain.MoveTo2(be, tgtPos, params_ ) -- Static

    assert( params_.smoothTime > 0.0 ) -- 0.3
    assert( params_.maxSpeed > 0.0 ) -- 30
    print( "==== MoveTo2 ==== B, smoothTime = " .. params_.smoothTime .. ", maxSpeed = " .. params_.maxSpeed )

    local currentMoveVelocity = Vector3.zero
    while true do 
        be.position, currentMoveVelocity = Vector3.SmoothDamp( be.position, tgtPos, currentMoveVelocity, params_.smoothTime, params_.maxSpeed )
        if (be.position - tgtPos).magnitude < 0.01 then 
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end 
end




-- 被各个 Puzzle 广泛使用:
---@param eventKey EventKey
---@return void
function MazeMain:AddToCatchedEventKeys(eventKey)
    table.insert( self.catchedEventKeys, eventKey) -- 插入尾后
end



---@param trackNodeGOID integer
---@return void
function MazeMain:HideCurrentGearBubble(trackNodeGOID)

    -- 通常来讲, 当进入解谜环节后, tmpBubbles 中存在的元素, 大部分都是 gear; 以下实现是基于这个特性去做的:
    for keyId,bubble in pairs(self.tmpBubbles) do

        if bubble.eventType == MazeEventType.Get().Gear then
        
            if keyId == trackNodeGOID  then
                bubble.gameObj:SetActive( false )
            else 
                bubble.gameObj:SetActive( true )
            end
        end
    end
end


---@param trackNodeGOID integer
---@return void
function MazeMain:ShowGearBubbleWhenLeaveGear(trackNodeGOID)

    local bubble = self.tmpBubbles[trackNodeGOID] -- MazeUI_Bubble
    if  isNull(bubble) or (bubble.eventType ~= MazeEventType.Get().Gear) then

        -- 通常来讲, 当进入解谜环节后, tmpBubbles 中存在的元素, 大部分都是 gear; 以下实现是基于这个特性去做的:
        for keyId,bubble2 in pairs(self.tmpBubbles) do
            if bubble2.eventType ~= MazeEventType.Get().Gear then
                -- continue
            else
                if bubble2.gameObj.activeSelf == false  then
                    bubble2.gameObj:SetActive( true )
                end
            end
        end
    end
end


---@param trackNodeGO TrackNodeGO
---@return void
function MazeMain:MoveRoleToTrackNodeGOImmediately(trackNodeGO)
    self.last2TrackNodeGO = self.lastTrackNodeGO -- 就算是瞬移, 也要留着 上上一次的 节点
    self.lastTrackNodeGO = trackNodeGO
    self.nextTrackNodeGO = trackNodeGO
    self.tgtTrackNodeGO = trackNodeGO
end


---@param roomKey string, "2-up" 这种
---@param isTurnOn boolean
---@return System.Collections.IEnumerator
function MazeMain:ControlRoomLight(roomKey, isTurnOn )
    --print( "点亮room: " .. tostring(roomKey) )
    local room = self.lightRoomsDic[roomKey]
    assert( isTable(room) )
    for i,sr in pairs(room) do
        --print( sr.name )
        sr.enabled = isTurnOn
    end
end


-- 大横栏:
-- stage_: 允许为 nil
function MazeMain:OpenDialogEventResultPopup( refId_, eventResType_, stage_ )

    UIModule.OpenDialog({ 
        id = Constants.UITypeIds.MapDecryptionEventResultPopup, 
        parameters = {
            data = {
                refId = refId_,
                eventResType = eventResType_,
                stage = stage_
            }
        }
    })
    -- 播放音效: 
    Maze2DSounds.PlayMusic( Maze2DSounds.musics.ui_festival_map_popup )
    -- 等待 大横栏 界面被关闭:
    Maze2DStates.isDialogEventResultPopupShow = true
    while Maze2DStates.isDialogEventResultPopupShow == true do 
        coroutine.yield(Yielders.EndOfFrame)
    end 

end





return MazeMain
